// P4-06 compatibility: records and documents produced by the code at split-manifest EPOCH 2 (the seven circuits of P4-04), BEFORE Silverstone was
// registered (the fixtures in tests/fixtures/pre-p4-06 were generated by the unchanged code of main at ebefd7e, then committed first, before any
// manifest change) must keep parsing and replaying after the registry grows again. Each is checked with its own recorded engine, so this is about the track registry, not the Node version.
// Mechanics fixtures only (seeds 78xx); nothing here is a study result or evidence of learning.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { checkpointValidateOptions } from '../../src/ui/checkpointAdapter';
import { validateCheckpoint } from '../../src/persistence/checkpointFormat';
import { importModelText } from '../../src/persistence/modelImport';
import { parseE3RulesRecord, parseE3SeedRecord, replayE3RulesRecord, replayE3SeedRecord } from '../../src/training/e3Study';
import { parseE4Record, replayE4Record } from '../../src/training/e4Study';
import { manifestEpochOf, parseExperimentRecord, replayExperiment } from '../../src/training/experiment';
import { parseStudyRecord, replayStudyRecord } from '../../src/training/study';
import { tracksIn } from '../../src/training/trackSplits';

type Json = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
const DIR = join(__dirname, '../fixtures/pre-p4-06');
const load = (name: string): Json => JSON.parse(readFileSync(join(DIR, name), 'utf8')) as Json;

describe('records made before the split expansion still parse and replay', () => {
  it('an experiment record', () => {
    const record = load('experiment-record.json');
    expect(parseExperimentRecord(record, record.engine).tracks.training.id).toBe('stadium-oval');
    // It recorded the epoch-2 split manifest (seven circuits); it must still be recognised as epoch 2 once an eighth circuit exists.
    expect(manifestEpochOf(record.tracks.manifest)).toBe(2);
    expect(record.tracks.manifest.entries).toHaveLength(7);
    expect(replayExperiment(record, record.engine).identical).toBe(true);
  });
  it('a P2-08 study record and its manifest', () => {
    const record = load('study-record.json');
    const manifest = load('study-manifest.json');
    expect(parseStudyRecord(record, manifest, record.engine).seed).toBe(7911);
    expect(replayStudyRecord(record, manifest, record.engine).identical).toBe(true);
  });
  it('an E4 record and its manifest', () => {
    const record = load('e4-record.json');
    const manifest = load('e4-manifest.json');
    expect(parseE4Record(record, manifest, record.engine).seed).toBe(7921);
    expect(replayE4Record(record, manifest, record.engine).identical).toBe(true);
  });
  it('an E3 seed record and rules record, and their manifest', () => {
    const manifest = load('e3-manifest.json');
    const seed = load('e3-seed-record.json');
    const rules = load('e3-rules-record.json');
    expect(parseE3SeedRecord(seed, manifest, seed.engine).seed).toBe(7931);
    expect(replayE3SeedRecord(seed, manifest, seed.engine).identical).toBe(true);
    expect(parseE3RulesRecord(rules, manifest, rules.engine)).toBeTruthy();
    expect(replayE3RulesRecord(rules, manifest, rules.engine).identical).toBe(true);
  });
  it('a checkpoint', () => {
    const result = validateCheckpoint(load('checkpoint.json'), checkpointValidateOptions());
    if (!result.ok) throw new Error(result.errors.join('; '));
  });
  it('a saved model made at epoch 2 (a seeded one-generation champion, trained on the stadium oval)', () => {
    const text = readFileSync(join(DIR, 'champion.json'), 'utf8');
    const result = importModelText(text, { registry: tracksIn('training') });
    if (!result.ok) throw new Error(result.errors.join(' '));
    expect(result.drivable).toBe(true);
  });
});
